"""The UI's real request bodies (contracts/requests, generated by the frontend adapter) replayed
against the API and Postgres in the order the screens send them: first-time user's profile ->
new resume -> JD -> wizard autosave -> full tailor -> settings -> save to profile."""

import json
from pathlib import Path

import pytest

pytestmark = pytest.mark.db

REQUESTS = Path(__file__).resolve().parents[3] / "contracts" / "requests"


def body(name: str) -> dict:
    return json.loads((REQUESTS / name).read_text(encoding="utf-8"))


def echo_tailor(user_message: str) -> dict:
    """cv_tailor that changes nothing: proves the job runs on wizard-saved content."""
    data = json.loads(user_message[user_message.index("{"):])
    return {"experience_order": [i["id"] for i in data["items"] if i["kind"] == "experience"],
            "items": [{"id": i["id"], "bullets": [{"id": b["id"], "text": b["text"]}
                                                  for b in i["bullets"]]} for i in data["items"]],
            "skills": data["skills"], "missing_skills": []}


async def test_ui_requests_drive_the_whole_flow(api):
    h = api.new_user()
    c = api.client

    r = await c.put("/profile", json=body("profile_put_new.json"), headers=h)
    assert r.status_code == 200, r.text

    r = await c.post("/resumes", json=body("create_resume.json"), headers=h)
    assert r.status_code == 201, r.text
    rid, version = r.json()["id"], r.json()["row_version"]

    r = await c.put(f"/resumes/{rid}/jd", json=body("set_jd.json"), headers=h)
    assert (r.status_code, r.json()["company"]) == (200, "Freshworks"), r.text

    for section in ("personal", "experience", "projects", "education", "skills"):
        patch = {**body(f"resume_patch_{section}.json"), "expected_version": version}
        r = await c.patch(f"/resumes/{rid}", json=patch, headers=h)
        assert r.status_code == 200, (section, r.text)
        version = r.json()["row_version"]

    resume = (await c.get(f"/resumes/{rid}", headers=h)).json()
    assert resume["wizard_step"] == "done"
    assert resume["content"]["header"]["links"][0]["label"] == "LinkedIn"

    api.provider.push(echo_tailor)
    r = await c.post(f"/resumes/{rid}/tailor", json=body("tailor.json"), headers=h)
    assert r.status_code == 202, r.text
    resume = (await c.get(f"/resumes/{rid}", headers=h)).json()
    assert (resume["status"], resume["job_step"]) == ("ready", None), resume["error_code"]

    r = await c.put("/settings", json=body("settings_put.json"), headers=h)
    assert r.json()["product_emails"] is True

    profile_version = (await c.get("/profile", headers=h)).json()["row_version"]
    r = await c.post(f"/resumes/{rid}/save-to-profile", headers=h,
                     json={"expected_version": profile_version})
    assert r.status_code == 200, r.text
